// ---- semanas ----
const mondayOf = (d) => {
  const x = new Date(d);
  const day = (x.getDay() + 6) % 7;
  x.setDate(x.getDate() - day);
  x.setHours(0, 0, 0, 0);
  return x;
};
const keyOf = (d) => {
  const m = mondayOf(d);
  return `${m.getFullYear()}-${String(m.getMonth() + 1).padStart(2, "0")}-${String(m.getDate()).padStart(2, "0")}`;
};
const labelOf = (key) => {
  const [y, m, d] = key.split("-").map(Number);
  const start = new Date(y, m - 1, d);
  const end = new Date(start);
  end.setDate(end.getDate() + 6);
  const f = (x) => `${x.getDate()} ${["ene", "feb", "mar", "abr", "may", "jun", "jul", "ago", "sep", "oct", "nov", "dic"][x.getMonth()]}`;
  return `${f(start)} – ${f(end)}`;
};
const shiftWeek = (key, n) => {
  const [y, m, d] = key.split("-").map(Number);
  const x = new Date(y, m - 1, d);
  x.setDate(x.getDate() + n * 7);
  return keyOf(x);
};

function MiEntreno() {
  const [plan, setPlan] = useState(DEFAULT_PLAN);
  const [logs, setLogs] = useState({});
  const [loaded, setLoaded] = useState(false);
  const [dayIdx, setDayIdx] = useState(0);
  const [week, setWeek] = useState(keyOf(new Date()));
  const [editing, setEditing] = useState(false);
  const [openNote, setOpenNote] = useState(null);
  const [zoom, setZoom] = useState(null);
  const [timer, setTimer] = useState(null);
  const [party, setParty] = useState(false);
  const audioRef = useRef(null);
  const wakeRef = useRef(null);

  useEffect(() => {
    (async () => {
      try {
        const r = store.get("entreno:plan");
        if (r?.value) setPlan(JSON.parse(r.value));
      } catch (e) {}
      try {
        const r = store.get("entreno:logs");
        if (r?.value) setLogs(JSON.parse(r.value));
      } catch (e) {}
      setLoaded(true);
    })();
  }, []);

  useEffect(() => {
    if (!loaded) return;
    const t = setTimeout(() => {
      store.set("entreno:plan", JSON.stringify(plan));
    }, 400);
    return () => clearTimeout(t);
  }, [plan, loaded]);

  useEffect(() => {
    if (!loaded) return;
    const t = setTimeout(() => {
      store.set("entreno:logs", JSON.stringify(logs));
    }, 400);
    return () => clearTimeout(t);
  }, [logs, loaded]);

  // ---- timer ----
  useEffect(() => {
    if (!timer || !timer.running) return;
    const i = setInterval(() => {
      setTimer((t) => {
        if (!t || !t.running) return t;
        const left = Math.max(0, Math.round((t.endAt - Date.now()) / 1000));
        if (left <= 0) {
          ring();
          return { ...t, left: 0, running: false, done: true };
        }
        return { ...t, left };
      });
    }, 300);
    return () => clearInterval(i);
  }, [timer?.running]);

  const ring = () => {
    try {
      const ctx = audioRef.current;
      if (ctx) {
        [0, 0.22, 0.44].forEach((d) => {
          const o = ctx.createOscillator();
          const g = ctx.createGain();
          o.frequency.value = 880;
          o.type = "sine";
          g.gain.setValueAtTime(0.0001, ctx.currentTime + d);
          g.gain.exponentialRampToValueAtTime(0.3, ctx.currentTime + d + 0.02);
          g.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + d + 0.18);
          o.connect(g).connect(ctx.destination);
          o.start(ctx.currentTime + d);
          o.stop(ctx.currentTime + d + 0.2);
        });
      }
    } catch (e) {}
    try {
      navigator.vibrate?.([200, 100, 200]);
    } catch (e) {}
  };

  const startTimer = (secs, label) => {
    try {
      if (!audioRef.current) audioRef.current = new (window.AudioContext || window.webkitAudioContext)();
      audioRef.current.resume?.();
    } catch (e) {}
    try {
      navigator.wakeLock?.request("screen").then((l) => (wakeRef.current = l)).catch(() => {});
    } catch (e) {}
    setTimer({ total: secs, left: secs, running: true, endAt: Date.now() + secs * 1000, label, done: false });
  };

  // ---- datos derivados ----
  const day = plan[dayIdx] || plan[0];
  const weekLog = logs[week] || {};

  const getSets = (exercise) => {
    const stored = weekLog[exercise.id]?.sets || [];
    return Array.from({ length: exercise.sets }, (_, i) => stored[i] || { w: "", r: "", done: false });
  };

  const updateSet = (exercise, i, patch) => {
    setLogs((prev) => {
      const wk = { ...(prev[week] || {}) };
      const cur = wk[exercise.id] || { sets: [], note: "" };
      const sets = Array.from({ length: exercise.sets }, (_, k) => cur.sets?.[k] || { w: "", r: "", done: false });
      sets[i] = { ...sets[i], ...patch };
      wk[exercise.id] = { ...cur, sets };
      return { ...prev, [week]: wk };
    });
  };

  const setNote = (exercise, text) => {
    setLogs((prev) => {
      const wk = { ...(prev[week] || {}) };
      const cur = wk[exercise.id] || { sets: [], note: "" };
      wk[exercise.id] = { ...cur, note: text };
      return { ...prev, [week]: wk };
    });
  };

  const lastTime = (exercise) => {
    const keys = Object.keys(logs)
      .filter((k) => k < week && logs[k]?.[exercise.id]?.sets?.some((s) => s && (s.w || s.r)))
      .sort();
    if (!keys.length) return null;
    const k = keys[keys.length - 1];
    return logs[k][exercise.id].sets.filter((s) => s && (s.w || s.r));
  };

  const dayProgress = useMemo(() => {
    let total = 0,
      done = 0;
    day?.exercises.forEach((e) => {
      total += e.sets;
      done += getSets(e).filter((s) => s.done).length;
    });
    return { total, done };
  }, [day, weekLog, plan]);

  useEffect(() => {
    if (dayProgress.total > 0 && dayProgress.done === dayProgress.total) {
      setParty(true);
      const t = setTimeout(() => setParty(false), 2600);
      return () => clearTimeout(t);
    }
  }, [dayProgress.done, dayProgress.total]);

  // ---- edición ----
  const mutateDay = (fn) =>
    setPlan((prev) => prev.map((d, i) => (i === dayIdx ? fn({ ...d, exercises: [...d.exercises] }) : d)));

  const editEx = (id, patch) =>
    mutateDay((d) => {
      d.exercises = d.exercises.map((e) =>
        e.id === id ? { ...e, img: e.img || norm(e.name), ...patch } : e
      );
      return d;
    });

  const removeEx = (id) =>
    mutateDay((d) => {
      d.exercises = d.exercises.filter((e) => e.id !== id);
      return d;
    });

  const moveEx = (id, dir) =>
    mutateDay((d) => {
      const i = d.exercises.findIndex((e) => e.id === id);
      const j = i + dir;
      if (j < 0 || j >= d.exercises.length) return d;
      [d.exercises[i], d.exercises[j]] = [d.exercises[j], d.exercises[i]];
      return d;
    });

  const addEx = () =>
    mutateDay((d) => {
      d.exercises = [...d.exercises, ex("Ejercicio nuevo", 3, "10", 90)];
      return d;
    });

  const moveToDay = (id, targetIdx) => {
    if (targetIdx === dayIdx) return;
    setPlan((prev) => {
      const item = prev[dayIdx].exercises.find((e) => e.id === id);
      if (!item) return prev;
      return prev.map((d, i) => {
        if (i === dayIdx) return { ...d, exercises: d.exercises.filter((e) => e.id !== id) };
        if (i === targetIdx) return { ...d, exercises: [...d.exercises, item] };
        return d;
      });
    });
  };

  const resetPlan = () => {
    if (confirm("¿Volver al plan original de tus PDFs? Tus registros de peso y reps se mantienen.")) {
      setPlan(DEFAULT_PLAN);
    }
  };

  const fmt = (s) => `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
  const isThisWeek = week === keyOf(new Date());

  return (
    <div style={{ background: C.bg, color: C.ink, minHeight: "100vh", fontFamily: "'Quicksand', ui-rounded, system-ui, sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@500;600&family=Quicksand:wght@500;600;700&display=swap');
        .disp { font-family: 'Fredoka', ui-rounded, system-ui, sans-serif; }
        input, select, textarea { font-family: inherit; }
        input:focus-visible, button:focus-visible, select:focus-visible, textarea:focus-visible {
          outline: 2px solid ${C.pink}; outline-offset: 2px;
        }
        @keyframes pop { 0% { transform: scale(.6); } 60% { transform: scale(1.25); } 100% { transform: scale(1); } }
        .pop { animation: pop .32s ease-out; }
        @keyframes floatUp { 0% { transform: translateY(0) scale(.6); opacity: 0; } 15% { opacity: 1; } 100% { transform: translateY(-320px) scale(1.1); opacity: 0; } }
        .conf { position: absolute; bottom: 0; animation: floatUp 2.4s ease-out forwards; }
        @media (prefers-reduced-motion: reduce) { .pop, .conf { animation: none; } }
      `}</style>

      {/* Cabecera */}
      <header className="px-4 pb-4 rounded-b-3xl" style={{ background: C.pink, color: "#fff", paddingTop: "calc(env(safe-area-inset-top) + 20px)" }}>
        <div className="flex items-center justify-between">
          <h1 className="disp text-2xl">Mi entreno</h1>
          <button
            onClick={() => setEditing((v) => !v)}
            className="text-sm px-3 py-1.5 rounded-full"
            style={{ background: editing ? "#fff" : "rgba(255,255,255,.22)", color: editing ? C.pinkDeep : "#fff", fontWeight: 700 }}
          >
            {editing ? "Listo" : "Editar"}
          </button>
        </div>

        <div className="flex items-center justify-between mt-3">
          <button onClick={() => setWeek(shiftWeek(week, -1))} className="px-3 py-1 text-lg" aria-label="Semana anterior">‹</button>
          <div className="text-center">
            <div className="text-sm" style={{ fontWeight: 700 }}>{labelOf(week)}</div>
            {!isThisWeek && (
              <button onClick={() => setWeek(keyOf(new Date()))} className="text-xs underline opacity-90">
                Ir a esta semana
              </button>
            )}
          </div>
          <button onClick={() => setWeek(shiftWeek(week, 1))} className="px-3 py-1 text-lg" aria-label="Semana siguiente">›</button>
        </div>
      </header>

      {/* Días */}
      <nav className="flex gap-2 overflow-x-auto px-4 py-3">
        {plan.map((d, i) => (
          <button
            key={d.id}
            onClick={() => { setDayIdx(i); setEditing(false); }}
            className="shrink-0 px-3.5 py-2 rounded-2xl text-sm text-left"
            style={{
              background: i === dayIdx ? C.ink : "#fff",
              color: i === dayIdx ? "#fff" : C.ink,
              border: `1.5px solid ${i === dayIdx ? C.ink : C.line}`,
              fontWeight: 700,
            }}
          >
            <div>{d.name}</div>
            <div className="text-[11px] opacity-70">{d.focus}</div>
          </button>
        ))}
      </nav>

      {/* Progreso del día */}
      <div className="px-4 pb-2 flex items-center gap-2">
        <div className="flex gap-0.5">
          {Array.from({ length: Math.min(dayProgress.total, 14) }, (_, i) => (
            <Heart key={i} filled={i < dayProgress.done} size={13} />
          ))}
        </div>
        <span className="text-xs" style={{ color: C.muted, fontWeight: 700 }}>
          {dayProgress.done}/{dayProgress.total} series
        </span>
      </div>

      {/* Ejercicios */}
      <main className="px-4 pb-40 space-y-3">
        {day?.exercises.length === 0 && (
          <p className="text-sm py-8 text-center" style={{ color: C.muted }}>
            Este día está vacío. Entra en Editar y añade tu primer ejercicio.
          </p>
        )}

        {day?.exercises.map((e) => {
          const sets = getSets(e);
          const prev = lastTime(e);
          const note = weekLog[e.id]?.note || "";
          return (
            <section key={e.id} className="rounded-3xl p-4" style={{ background: "#fff", border: `1.5px solid ${C.line}` }}>
              {editing ? (
                <div className="space-y-2">
                  <input
                    value={e.name}
                    onChange={(ev) => editEx(e.id, { name: ev.target.value })}
                    className="w-full px-3 py-2 rounded-xl text-sm"
                    style={{ border: `1.5px solid ${C.line}`, fontWeight: 700 }}
                  />
                  <div className="flex gap-2">
                    <label className="flex-1 text-[11px]" style={{ color: C.muted }}>
                      Series
                      <input
                        type="number" min="1" max="10" inputMode="numeric"
                        value={e.sets}
                        onChange={(ev) => editEx(e.id, { sets: Math.max(1, Math.min(10, +ev.target.value || 1)) })}
                        className="w-full px-2 py-2 rounded-xl text-sm" style={{ border: `1.5px solid ${C.line}` }}
                      />
                    </label>
                    <label className="flex-1 text-[11px]" style={{ color: C.muted }}>
                      Reps
                      <input
                        value={e.reps}
                        onChange={(ev) => editEx(e.id, { reps: ev.target.value })}
                        className="w-full px-2 py-2 rounded-xl text-sm" style={{ border: `1.5px solid ${C.line}` }}
                      />
                    </label>
                    <label className="flex-1 text-[11px]" style={{ color: C.muted }}>
                      Descanso (s)
                      <input
                        type="number" min="0" inputMode="numeric"
                        value={e.rest}
                        onChange={(ev) => editEx(e.id, { rest: +ev.target.value || 0 })}
                        className="w-full px-2 py-2 rounded-xl text-sm" style={{ border: `1.5px solid ${C.line}` }}
                      />
                    </label>
                  </div>
                  <div className="flex flex-wrap items-center gap-2 pt-1">
                    <button onClick={() => moveEx(e.id, -1)} className="px-3 py-1.5 rounded-full text-xs" style={{ background: C.pinkSoft, fontWeight: 700 }}>↑ Subir</button>
                    <button onClick={() => moveEx(e.id, 1)} className="px-3 py-1.5 rounded-full text-xs" style={{ background: C.pinkSoft, fontWeight: 700 }}>↓ Bajar</button>
                    <select
                      onChange={(ev) => moveToDay(e.id, +ev.target.value)}
                      value={dayIdx}
                      className="px-2 py-1.5 rounded-full text-xs"
                      style={{ background: "#F3ECFA", fontWeight: 700 }}
                    >
                      {plan.map((d, i) => (
                        <option key={d.id} value={i}>
                          {i === dayIdx ? "Mover a…" : `→ ${d.name} · ${d.focus}`}
                        </option>
                      ))}
                    </select>
                    <button onClick={() => removeEx(e.id)} className="px-3 py-1.5 rounded-full text-xs ml-auto" style={{ color: C.pinkDeep, fontWeight: 700 }}>Quitar</button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="flex items-start gap-3">
                    {imgFor(e) && (
                      <button
                        onClick={() => setZoom({ src: imgFor(e), name: e.name })}
                        className="shrink-0 rounded-2xl overflow-hidden"
                        style={{ width: 64, height: 64, background: "#fff", border: `1.5px solid ${C.line}` }}
                        aria-label={`Ver ${e.name} en grande`}
                      >
                        <img src={imgFor(e)} alt={e.name} className="w-full h-full object-contain p-0.5" />
                      </button>
                    )}
                    <div className="min-w-0 flex-1">
                      <h2 className="text-[15px] leading-snug" style={{ fontWeight: 700 }}>{e.name}</h2>
                      <p className="text-xs mt-0.5" style={{ color: C.muted, fontWeight: 700 }}>
                        {e.sets} × {e.reps} · descanso {e.rest}s
                      </p>
                    </div>
                    {e.note && (
                      <button
                        onClick={() => setOpenNote(openNote === e.id ? null : e.id)}
                        className="shrink-0 w-7 h-7 rounded-full text-xs"
                        style={{ background: C.pinkSoft, color: C.pinkDeep, fontWeight: 700 }}
                        aria-label="Ver la indicación de tu entrenadora"
                      >
                        ?
                      </button>
                    )}
                  </div>
                  {openNote === e.id && (
                    <p className="text-xs mt-2 p-2.5 rounded-2xl leading-relaxed" style={{ background: "#FFF0F5", color: C.pinkDeep }}>
                      {e.note}
                    </p>
                  )}
                  {prev && (
                    <p className="text-[11px] mt-2" style={{ color: C.lilac, fontWeight: 700 }}>
                      La última vez: {prev.map((s) => `${s.w || "–"}kg × ${s.r || "–"}`).join("  ·  ")}
                    </p>
                  )}

                  <div className="mt-3 space-y-2">
                    {sets.map((s, i) => (
                      <div key={i} className="flex items-center gap-2">
                        <span className="w-5 text-xs text-center" style={{ color: C.muted, fontWeight: 700 }}>{i + 1}</span>
                        <input
                          inputMode="decimal" placeholder="kg" value={s.w}
                          onChange={(ev) => updateSet(e, i, { w: ev.target.value })}
                          className="w-full min-w-0 px-3 py-2.5 rounded-2xl text-sm text-center"
                          style={{ background: C.bg, border: `1.5px solid ${C.line}`, fontWeight: 700 }}
                        />
                        <input
                          inputMode="decimal" placeholder="reps" value={s.r}
                          onChange={(ev) => updateSet(e, i, { r: ev.target.value })}
                          className="w-full min-w-0 px-3 py-2.5 rounded-2xl text-sm text-center"
                          style={{ background: C.bg, border: `1.5px solid ${C.line}`, fontWeight: 700 }}
                        />
                        <button
                          onClick={() => {
                            const next = !s.done;
                            updateSet(e, i, { done: next });
                            if (next && e.rest > 0) startTimer(e.rest, e.name);
                          }}
                          className={s.done ? "pop shrink-0 p-1" : "shrink-0 p-1"}
                          aria-label={s.done ? `Serie ${i + 1} hecha` : `Marcar serie ${i + 1}`}
                        >
                          <Heart filled={s.done} size={28} />
                        </button>
                      </div>
                    ))}
                  </div>

                  <input
                    value={note}
                    onChange={(ev) => setNote(e, ev.target.value)}
                    placeholder="Notas de hoy…"
                    className="w-full mt-2 px-3 py-2 rounded-2xl text-xs"
                    style={{ background: "#FFFBFC", border: `1.5px dashed ${C.line}` }}
                  />
                </>
              )}
            </section>
          );
        })}

        {editing && (
          <div className="space-y-2 pt-1">
            <button onClick={addEx} className="w-full py-3 rounded-3xl text-sm" style={{ background: C.pink, color: "#fff", fontWeight: 700 }}>
              + Añadir ejercicio
            </button>
            <button
              onClick={() => {
                const blob = new Blob([JSON.stringify({ plan, logs }, null, 2)], { type: "application/json" });
                const a = document.createElement("a");
                a.href = URL.createObjectURL(blob);
                a.download = `mi-entreno-${keyOf(new Date())}.json`;
                a.click();
              }}
              className="w-full py-2.5 rounded-3xl text-sm"
              style={{ background: "#fff", color: C.pinkDeep, border: `1.5px solid ${C.pinkSoft}`, fontWeight: 700 }}
            >
              Guardar copia de mis datos
            </button>
            <button onClick={resetPlan} className="w-full py-2 text-xs" style={{ color: C.muted, fontWeight: 700 }}>
              Restaurar el plan original
            </button>
          </div>
        )}
      </main>

      {/* Temporizador */}
      {timer && (
        <div className="fixed left-0 right-0 bottom-0 px-4 pb-4">
          <div className="relative rounded-3xl p-4 flex items-center gap-4 shadow-lg" style={{ background: C.ink, color: "#fff" }}>
            <div className="relative shrink-0" style={{ width: 54, height: 54 }}>
              <svg viewBox="0 0 24 24" width="54" height="54">
                <defs>
                  <clipPath id="fillClip">
                    <rect x="0" y={24 - 24 * (timer.left / timer.total)} width="24" height={24 * (timer.left / timer.total)} />
                  </clipPath>
                </defs>
                <path d={HEART} fill="none" stroke="rgba(255,255,255,.35)" strokeWidth="1.6" />
                <path d={HEART} fill={C.pink} clipPath="url(#fillClip)" />
              </svg>
            </div>
            <div className="min-w-0 flex-1">
              <div className="disp text-3xl leading-none">{fmt(timer.left)}</div>
              <div className="text-[11px] truncate opacity-70 mt-1">
                {timer.done ? "¡Descanso terminado! A por la siguiente" : `Descansando · ${timer.label}`}
              </div>
            </div>
            <div className="flex flex-col gap-1.5 shrink-0">
              <button
                onClick={() => setTimer((t) => ({ ...t, left: t.left + 15, total: Math.max(t.total, t.left + 15), endAt: Date.now() + (t.left + 15) * 1000, running: true, done: false }))}
                className="px-3 py-1.5 rounded-full text-xs" style={{ background: "rgba(255,255,255,.15)", fontWeight: 700 }}
              >
                +15s
              </button>
              <button
                onClick={() => (timer.done ? setTimer(null) : setTimer((t) => ({ ...t, running: !t.running, endAt: Date.now() + t.left * 1000 })))}
                className="px-3 py-1.5 rounded-full text-xs" style={{ background: C.pink, fontWeight: 700 }}
              >
                {timer.done ? "Hecho" : timer.running ? "Pausa" : "Seguir"}
              </button>
              <button
                onClick={() => { try { wakeRef.current?.release?.(); wakeRef.current = null; } catch (e) {} setTimer(null); }}
                className="px-3 py-1.5 rounded-full text-xs" style={{ background: "rgba(255,255,255,.15)", fontWeight: 700 }}
              >
                Saltar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Imagen ampliada */}
      {zoom && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center p-6"
          style={{ background: "rgba(59,34,48,.72)" }}
          onClick={() => setZoom(null)}
        >
          <div className="rounded-3xl overflow-hidden max-w-sm w-full" style={{ background: "#fff" }}>
            <img src={zoom.src} alt={zoom.name} className="w-full" />
            <p className="px-4 py-3 text-sm text-center" style={{ fontWeight: 700 }}>{zoom.name}</p>
          </div>
        </div>
      )}

      {/* Corazones al terminar el día */}
      {party && (
        <div className="fixed inset-0 pointer-events-none overflow-hidden">
          {Array.from({ length: 14 }, (_, i) => (
            <div key={i} className="conf" style={{ left: `${6 + i * 6.6}%`, animationDelay: `${i * 0.11}s` }}>
              <Heart filled size={20 + (i % 4) * 7} color={i % 3 === 0 ? C.lilac : C.pink} />
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

createRoot(document.getElementById("root")).render(<MiEntreno />);
